inDiscipline(discipline) {
        const ret = [];
        // Check each laureate
        for (const laureate of this.laureates) {
            // Check each prize
            for (const prize of laureate.nobelPrizes) {
                // Check the category of the prize
                if (prize.category.en === discipline) {
                    ret.push(output(laureate));
                    break;
                }
            }
        }
        return ret;
    }

fromCountry(country) {
        const ret = [];
        // Check each laureate
        for (const laureate of this.laureates) {
            // Check the birth country of the laureate
            if (laureate.birth.place.country.en === country) {
                ret.push(output(laureate));
            }
        }
        return ret;
    }

function isParseUrlArgs(args: unknown): args is ParseUrlArgs {
  if (!args || typeof args !== 'object') return false;
  const a = args as Record<string, unknown>;
  return typeof a.url === 'string' &&
    (a.format === undefined || ['txt', 'html', 'pdf', 'json', 'csv', 'xmind'].includes(a.format as string));
}

