    }

    this.emit('file:access', agentId, dirPath, 'list');
    const result = await this.files.list(dirPath, agentId);
    this.audit({
      action: 'file_list', agentId, target: dirPath,
      result: result.success ? 'success' : 'error', durationMs: result.durationMs,
    });
    return result;
  }

