        const croppedFile = '/attachments/' + info._id + '-' + info.name + '.' + crop.left + '.' + crop.top + '.' + crop.width + '.' + crop.height + '.' + info.extension;
        await Promise.promisify(self.uploadfs.copyOut)(originalFile, tempFile);
