def _resolve_and_validate_host(host, port):
    """
    Resolve ``host`` once and SSRF-validate *every* address it resolves to.

    Returns the resolved ``getaddrinfo`` records so the caller can connect to a
    **pinned** numeric address. Because validation and the subsequent connection
    observe the same resolution (the connection is made to the numeric IP, which
    triggers no further name lookup), this closes the DNS-rebinding TOCTOU where
    a hostname resolves to a public IP during validation and to an internal /
    loopback IP during the actual connect.
    """
    try:
        addrinfo = socket.getaddrinfo(host, port, proto=socket.IPPROTO_TCP)
    except (OSError, ValueError):
        return []
    for res in addrinfo:
        try:
            ip = ipaddress.ip_address(res[4][0])
        except ValueError:
            continue
        if _ip_is_forbidden(ip):
            msg = f"Security Violation [pathsec.urlopen]: SSRF attempt to restricted IP {ip}"
            if ENFORCE:
                raise PermissionError(msg)
            warnings.warn(msg, RuntimeWarning, stacklevel=2)
    return addrinfo

def connect(self):
        self.sock = _pinned_connection(
            self.host, self.port, self.timeout, self.source_address
        )

def __repr__(self):
        """
        Return a string representation for this corpus view that is
        similar to a list's representation; but if it would be more
        than 60 characters long, it is truncated.
        """
        pieces = []
        length = 5

        for elt in self:
            pieces.append(
                elt._short_repr()
            )  # key difference from inherited version: call to _short_repr()
            length += len(pieces[-1]) + 2
            if self._MAX_REPR_SIZE and length > self._MAX_REPR_SIZE and len(pieces) > 2:
                return "[%s, ...]" % str(",\n " if self._BREAK_LINES else ", ").join(
                    pieces[:-1]
                )
        return "[%s]" % str(",\n " if self._BREAK_LINES else ", ").join(pieces)

def frame_ids_and_names(self, name=None):
        """
        Uses the frame index, which is much faster than looking up each frame definition
        if only the names and IDs are needed.
        """
        if not self._frame_idx:
            self._buildframeindex()
        return {
            fID: finfo.name
            for fID, finfo in self._frame_idx.items()
            if name is None or re.search(name, finfo.name) is not None
        }

def _matching_exs():
            for f in frames:
                fes = fes2 = None  # FEs of interest
                if fe is not None:
                    fes = (
                        {ffe for ffe in f.FE.keys() if re.search(fe, ffe, re.I)}
                        if isinstance(fe, str)
                        else {fe.name}
                    )
                    if fe2 is not None:
                        fes2 = (
                            {ffe for ffe in f.FE.keys() if re.search(fe2, ffe, re.I)}
                            if isinstance(fe2, str)
                            else {fe2.name}
                        )

                for lu in (
                    lusByFrame[f.name]
                    if luNamePattern is not None
                    else f.lexUnit.values()
                ):
                    for ex in lu.exemplars:
                        if (fes is None or self._exemplar_of_fes(ex, fes)) and (
                            fes2 is None or self._exemplar_of_fes(ex, fes2)
                        ):
                            yield ex

def ft_sents(self, docNamePattern=None):
        """
        Full-text annotation sentences, optionally filtered by document name.
        """
        return PrettyLazyIteratorList(
            sent for d in self.docs(docNamePattern) for sent in d.sentence
        )

def _handle_luannotationset_elt(self, elt, is_pos=False):
        """Load an annotation set from a sentence in an subcorpus of an LU"""
        info = self._load_xml_attributes(AttrDict(), elt)
        info["_type"] = "posannotationset" if is_pos else "luannotationset"
        info["layer"] = []
        info["_ascii"] = types.MethodType(
            _annotation_ascii, info
        )  # attach a method for this instance

        if "cxnID" in info:  # ignoring construction annotations for now.
            return info

        for sub in elt:
            if sub.tag.endswith("layer"):
                l = self._handle_lulayer_elt(sub)
                if l is not None:
                    overt = []
                    ni = {}  # null instantiations

                    info["layer"].append(l)
                    for lbl in l.label:
                        if "start" in lbl:
                            thespan = (lbl.start, lbl.end + 1, lbl.name)
                            if l.name not in (
                                "Sent",
                                "Other",
                            ):  # 'Sent' and 'Other' layers sometimes contain accidental duplicate spans
                                assert thespan not in overt, (info.ID, l.name, thespan)
                            overt.append(thespan)
                        else:  # null instantiation
                            if lbl.name in ni:
                                self._warn(
                                    "FE with multiple NI entries:",
                                    lbl.name,
                                    ni[lbl.name],
                                    lbl.itype,
                                )
                            else:
                                ni[lbl.name] = lbl.itype
                    overt = sorted(overt)

                    if l.name == "Target":
                        if not overt:
                            self._warn(
                                "Skipping empty Target layer in annotation set ID={}".format(
                                    info.ID
                                )
                            )
                            continue
                        assert all(lblname == "Target" for i, j, lblname in overt)
                        if "Target" in info:
                            self._warn(
                                "Annotation set {} has multiple Target layers".format(
                                    info.ID
                                )
                            )
                        else:
                            info["Target"] = [(i, j) for (i, j, _) in overt]
                    elif l.name == "FE":
                        if l.rank == 1:
                            assert "FE" not in info
                            info["FE"] = (overt, ni)
                            # assert False,info
                        else:
                            # sometimes there are 3 FE layers! e.g. Change_position_on_a_scale.fall.v
                            assert 2 <= l.rank <= 3, l.rank
                            k = "FE" + str(l.rank)
                            assert k not in info
                            info[k] = (overt, ni)
                    elif l.name in ("GF", "PT"):
                        assert l.rank == 1
                        info[l.name] = overt
                    elif l.name in ("BNC", "PENN"):
                        assert l.rank == 1
                        info["POS"] = overt
                        info["POS_tagset"] = l.name
                    else:
                        if is_pos:
                            if l.name not in ("NER", "WSL"):
                                self._warn(
                                    "Unexpected layer in sentence annotationset:",
                                    l.name,
                                )
                        else:
                            if l.name not in (
                                "Sent",
                                "Verb",
                                "Noun",
                                "Adj",
                                "Adv",
                                "Prep",
                                "Scon",
                                "Art",
                                "Other",
                            ):
                                self._warn(
                                    "Unexpected layer in frame annotationset:", l.name
                                )
                        info[l.name] = overt
        if not is_pos and "cxnID" not in info:
            if "Target" not in info:
                self._warn(f"Missing target in annotation set ID={info.ID}")
            assert "FE" in info
            if "FE3" in info:
                assert "FE2" in info

        return info

def __new__(cls, etree):
        """
        Create and return a wrapper around a given Element object.
        If ``etree`` is an ``ElementWrapper``, then ``etree`` is
        returned as-is.
        """
        if isinstance(etree, ElementWrapper):
            return etree
        else:
            return object.__new__(ElementWrapper)

def api_tags_and_tagged_list(request, conn=None, **kwargs):
    if request.method == "GET":
        return api_tags_and_tagged_list_GET(request, conn, **kwargs)
    elif request.method == "DELETE":
        return api_tags_and_tagged_list_DELETE(request, conn, **kwargs)

def api_tags_and_tagged_list_GET(request, conn=None, **kwargs):
    """Get a list of tags
    Specifiying tag_id will return any sub-tags, sub-tagsets and
    objects tagged with that id
    If no tagset_id is specifed it will return tags which have no
    parent
    """
    # Get parameters
    try:
        page = get_long_or_default(request, "page", 1)
        limit = get_long_or_default(request, "limit", settings.PAGE)
        group_id = get_long_or_default(request, "group", -1)
        tag_id = get_long_or_default(request, "id", None)
        experimenter_id = get_long_or_default(request, "experimenter_id", -1)
        orphaned = get_bool_or_default(request, "orphaned", False)
        load_pixels = get_bool_or_default(request, "sizeXYZ", False)
        date = get_bool_or_default(request, "date", False)
    except ValueError:
        return HttpResponseBadRequest("Invalid parameter value")

    try:
        # Get ALL data (all owners) under specified tags
        if tag_id is not None:
            tagged = tree.marshal_tagged(
                conn=conn,
                experimenter_id=experimenter_id,
                tag_id=tag_id,
                group_id=group_id,
                page=page,
                load_pixels=load_pixels,
                date=date,
                limit=limit,
            )
        else:
            tagged = {}

        # Get 'tags' under tag_id
        tagged["tags"] = tree.marshal_tags(
            conn=conn,
            orphaned=orphaned,
            experimenter_id=experimenter_id,
            tag_id=tag_id,
            group_id=group_id,
            page=page,
            limit=limit,
        )
    except ApiUsageException as e:
        return HttpResponseBadRequest(e.serverStackTrace)
    except ServerError as e:
        return HttpResponseServerError(e.serverStackTrace)
    except IceException as e:
        return HttpResponseServerError(e.message)

    return JsonResponse(tagged)

def dryRun(request, action, conn=None, **kwargs):
    """Submit chgrp or chown dry-run"""
    targetObjects = {}
    dtypes = ["Project", "Dataset", "Image", "Screen", "Plate", "Fileset"]
    for dtype in dtypes:
        oids = request.POST.get(dtype, None)
        if oids is not None:
            obj_ids = [int(oid) for oid in oids.split(",")]
            targetObjects[dtype] = obj_ids

    if action == "chgrp":
        target_id = getIntOrDefault(request, "group_id", None)
    elif action == "chown":
        target_id = getIntOrDefault(request, "owner_id", None)
    handle = conn.submitDryRun(action, targetObjects, target_id)
    jobId = str(handle)
    return HttpResponse(jobId)

def getObjectOwnerId(r):
        for t in ["Dataset", "Image", "Plate"]:
            ids = r.POST.get(t, None)
            if ids is not None:
                for o in list(conn.getObjects(t, ids.split(","))):
                    return o.getDetails().owner.id.val

def script_upload(request, conn=None, **kwargs):
    """Script upload UI"""

    if request.method != "POST":
        return {"template": "webclient/scripts/upload_script.html"}

    # Get script path, name and text
    script_path = request.POST.get("script_path")
    script_file = request.FILES["script_file"]
    script_file.seek(0)
    script_text = script_file.read().decode("utf-8")

    if not script_path.endswith("/"):
        script_path = script_path + "/"
    script_path = script_path + script_file.name

    # If script exists, replace. Otherwise upload
    scriptService = conn.getScriptService()
    script_id = scriptService.getScriptID(script_path)

    try:
        if script_id > 0:
            orig_file = OriginalFileI(script_id, False)
            scriptService.editScript(orig_file, script_text)
            message = "Script Replaced: %s" % script_file.name
        else:
            script_id = scriptService.uploadOfficialScript(script_path, script_text)
            message = "Script Uploaded: %s" % script_file.name
    except omero.ValidationException as ex:
        message = str(ex)

    return {"Message": message, "script_id": script_id}

