def info(self):
        class _Meta:
            def getheaders(zelf, name):
                # PY2
                headers = self.response.headers.getRawHeaders(name, [])
                return headers

            def get_all(zelf, name, default):
                # PY3
                headers = self.response.headers.getRawHeaders(
